export interface AdminProduct {
  id: string;
  slug: string;
  name: string;
  category: 'decor' | 'lighting' | 'sacred' | 'accessories' | 'gifts';
  price: number;
  originalPrice?: number;
  material: string;
  dimensions: string;
  leadTime: string;
  description: string;
  colorGradient: string;
  iconName: string;
  imageUrl?: string;
  colors: string[];
  inStock: boolean;
  badge?: string;
  rating?: number;
  reviewsCount?: number;
  stockQuantity: number;
  salesCount: number;
}

export interface OrderItem {
  id: string;
  name: string;
  variant?: string;
  price: number;
  qty: number;
  imageUrl?: string;
}

export interface AdminOrder {
  id: string;
  date: string;
  customerName: string;
  customerPhone: string;
  customerEmail?: string;
  shippingAddress: string;
  city: string;
  pincode: string;
  notes?: string;
  items: OrderItem[];
  subtotal: number;
  deliveryFee: number;
  grandTotal: number;
  paymentMethod: 'UPI' | 'Card' | 'COD';
  paymentStatus: 'Paid' | 'Pending Verification' | 'COD Pending';
  orderStatus: 'Pending' | 'Slicing' | 'In Print Queue' | 'Quality Inspected' | 'Dispatched' | 'Delivered';
  printAssignedTo?: string;
  trackingNumber?: string;
}

export interface CustomEnquiry {
  id: string;
  date: string;
  customerName: string;
  customerPhone: string;
  customerEmail?: string;
  productReference?: string;
  fileAttachmentName?: string;
  fileSize?: string;
  estimatedGrams?: number;
  materialRequested: string;
  quantity: number;
  projectDetails: string;
  status: 'New Quote' | 'CAD Reviewing' | 'Quote Sent' | 'Approved' | 'Printing' | 'Completed';
  quotedPrice?: number;
  googleSheetsSynced: boolean;
}

export interface PaymentGatewaySettings {
  razorpay: {
    enabled: boolean;
    keyId: string;
    keySecret: string;
    testMode: boolean;
  };
  cashfree: {
    enabled: boolean;
    appId: string;
    secretKey: string;
    testMode: boolean;
  };
  upiDirect: {
    enabled: boolean;
    upiId: string;
    accountName: string;
    qrNote: string;
  };
  cod: {
    enabled: boolean;
    maxLimit: number;
    advanceRequiredPercent: number;
  };
  taxation: {
    gstEnabled: boolean;
    gstRatePercent: number;
    gstin: string;
    legalBusinessName: string;
  };
  shipping: {
    freeShippingThreshold: number;
    standardCourierFee: number;
    expressDeliveryFee: number;
    dispatchCity: string;
  };
}

export interface PrinterMachine {
  id: string;
  name: string;
  type: 'CoreXY FDM' | 'SLA Resin' | 'High-Speed FDM';
  buildVolume: string;
  status: 'Printing' | 'Idle' | 'Maintenance' | 'Calibrating';
  currentJob?: string;
  currentOrderRef?: string;
  currentProgress?: number;
  bedTemp: number;
  targetBedTemp: number;
  nozzleTemp: number;
  targetNozzleTemp: number;
  filamentRemainingPercent: number;
  filamentType: string;
  filamentColor: string;
  timeRemaining?: string;
}

